BEGIN
    IF value = '' THEN RETURN ''; END IF;
    -- Context uses the ORIGINAL characters and skips Case_Ignorable first,
    -- including characters which also have the Cased property.
    FOR i IN REVERSE cardinality(characters)..1 LOOP
        ch := characters[i];
        following_cased[i] := next_cased;
        IF NOT (ch COLLATE "C" ~ ignorable) THEN next_cased := ch COLLATE "C" ~ cased; END IF;
    END LOOP;
    FOR i IN 1..cardinality(characters) LOOP
        ch := characters[i];
        IF ch = 'Σ' AND previous_cased AND NOT following_cased[i] THEN
            result := result || 'ς';
        ELSIF ch = 'İ' THEN
            result := result || U&'i\0307';
        ELSE
            result := result || translate(ch, lowercase_from, lowercase_to);
        END IF;
        IF NOT (ch COLLATE "C" ~ ignorable) THEN previous_cased := ch COLLATE "C" ~ cased; END IF;
    END LOOP;
    RETURN result;
END;
