DO $preflight$
BEGIN
    IF EXISTS (SELECT 1 FROM public."User" WHERE "emailKey" <> public.usp_email_lower_v17(email)) THEN
        RAISE EXCEPTION 'Email mapping change requires a reviewed data migration';
    END IF;
END;
$preflight$;

ALTER TABLE public."User" DROP CONSTRAINT "User_email_policy";
ALTER TABLE public."User" ADD CONSTRAINT "User_email_policy" CHECK (
    char_length("email") BETWEEN 3 AND 254
    AND "email" = translate("email", E'\u0009\u000a\u000b\u000c\u000d\u0020\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff', '')
    AND "email" !~ '[[:space:][:cntrl:]]'
    AND "email" ~ '^[^@]+@[^@]+$'
    AND "emailKey" = public.usp_email_lower_v17("email")
    AND char_length("emailKey") BETWEEN 3 AND 254
);

COMMIT;
